function countDifferentSubsequenceGCDs(nums) {
  const gcd = (a, b) => (b === 0 ? a : gcd(b, a % b));
  const maxValue = Math.max(...nums);
  const present = new Array(maxValue + 1).fill(false);
  for (const num of nums) {
    present[num] = true;
  }
  let count = 0;

  for (let x = 1; x <= maxValue; x++) {
    let common = 0;
    for (let multiple = x; multiple <= maxValue; multiple += x) {
      if (present[multiple]) {
        common = gcd(common, multiple);
      }
      if (common === x) {
        break;
      }
    }
    if (common === x) {
      count++;
    }
  }
  return count;
}

